    "css": "@media (prefers-color-scheme: dark) {\n\n  :root {\n\n    // Increase brightness\n\n    --flatify__hover-brightness: 110%;\n\n    // Background color\n\n    --flatify__bg-color: #10191c !important;\n\n    --flatify__bg-color-dark: #141f23 !important;\n\n    --flatify__bg-color-darker: #263b43 !important;\n\n    --flatify__bg-color-darkest: #385661 !important;\n\n    --flatify__color-light-light: #141f23 !important;\n\n    --flatify__color-light-primary: #10191c !important;\n\n    --flatify__color-light-dark: #263b43 !important;\n\n    // Text color\n\n    --flatify__txt-color: #f1f4f7;\n\n    --flatify__txt-color-dark: #ced9e3;\n\n    --flatify__txt-color-darker: #809cb6;\n\n    --flatify__txt-color-inverted: #141f23;\n\n    --flatify__color-dark-light: #f1f4f7;\n\n    --flatify__color-dark-primary: #ced9e3;\n\n    --flatify__color-dark-dark: #809cb6;\n\n  }\n\n}\n\n\n\nhtml.dark {\n\n  @extend %dark-mode;\n\n}\n\n@media (prefers-color-scheme: dark) {\n\n  :root {\n\n    @extend %dark-mode;\n\n  }\n\n}\n\n.container {\n   flex-wrap: nowrap | wrap | wrap-reverse;\n  margin: 20px; \n  padding: 20px\n}\n\n.my-img-fx {\n  overflow: hidden;\n  width: 300px;\n  height: 150px;\n  margin: 0.5em;\n  border-radius: 1em;\n}\n.my-img-fx img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}\n\n.fx-1 {\n  --flatify__overlay-layer-bg-color: linear-gradient(to right, #2c5364, #203a43, #0f2027);\n  --flatify__overlay-layer-blending-mode: overlay;\n}\n\n.fx-2 {\n  --flatify__overlay-layer-bg-color: linear-gradient(to right, #8e2de2, #4a00e0);\n  --flatify__overlay-layer-blending-mode: hard-light;\n}\n\n.fx-3 {\n  --flatify__overlay-layer-bg-color: linear-gradient(to right, #f12711, #f5af19);\n  --flatify__overlay-layer-blending-mode: multiply;\n  --flatify__overlay-layer-opacity: 0.75;\n}\n\n.fx-4 {\n  --flatify__overlay-layer-bg-color: rgba(255, 255, 255, 0.5);\n  --flatify__overlay-layer-backdrop-filter: blur(3px) contrast(120%);\n}\n\n.fx-5 {\n  --flatify__overlay-layer-bg-color: trasparent;\n  --flatify__overlay-layer-backdrop-filter: contrast(400%) saturate(400%) grayscale(50%) sepia(50%) hue-rotate(10deg);\n}\n\n.fx-6 {\n  --flatify__overlay-layer-bg-color: trasparent;\n  --flatify__overlay-layer-backdrop-filter: sepia(75%) hue-rotate(-25deg);\n}\n\n.fx-7 {\n  --flatify__overlay-layer-bg-color: trasparent;\n  --flatify__overlay-layer-backdrop-filter: grayscale(100%) contrast(140%) brightness(85%);\n}\n\n$RESPONSIVE_BREAKPOINTS: (\n  xs: 575.98px,\n  sm: 576px,\n  md: 768px,\n  lg: 992px,\n  xl: 1200px,\n  xxl: 1400px,\n) !default;",
