om//docs/5.0/assets/js/docs.min.js\"></script>\n<style>\n * {\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n }\n\n html,\n body {\n  background-color: #000;\n  color: white;\n  height: 100%;\n  width: 100%;\n }\n\n a {\n  color: white;\n }\n\n .modalFull {\n  position: fixed;\n  top: 0;\n  right: 0;\n  bottom: 0;\n  left: 0;\n  z-index: 999;\n  display: none;\n  -webkit-overflow-scrolling: touch;\n  outline: 0;\n  overflow: hidden;\n }\n\n .closeModalFull {\n  font-size: 50px;\n  font-weight: 900;\n  line-height: 1;\n  color: #aaaaaa;\n  text-shadow: 0 1px 0 #fff;\n  filter: alpha(opacity=20);\n  opacity: 0.5;\n  position: fixed;\n  top: 30px;\n  right: 40px;\n  -webkit-appearance: none;\n  padding: 0;\n  cursor: pointer;\n  background: 0 0;\n  border: none;\n }\n\n .closeModalFull:hover,\n .closeModalFull:focus {\n  color: #000;\n  text-decoration: none;\n  cursor: pointer;\n  filter: alpha(opacity=50);\n  opacity: 0.5;\n }\n\n .closeModalFull:focus {\n  outline: none;\n }\n\n #modalContent {\n  height: 100%;\n  width: 100%;\n }\n</style>\n\n<div id=\"myModalFull\" class=\"modalFull\">\n <span class=\"closeModalFull\">&times;</span>\n <iframe id=\"modalContent\" src=\"\" name=\"iframe_a\" frameborder=\"0\" style=\"border:0;\"></iframe>\n</div>\n\n<script>\n // Get the modal\n var modal = document.getElementById(\"myModalFull\");\n // Get the button that opens the modal\n var btn = document.getElementById(\"myBtnFull\");\n // Get the <span> element that closes the modal\n var span = document.querySelector(\".closeModalFull\");\n // Get all modal links\n var modalLinks = document.querySelectorAll(\".modalLink\");\n // Get the iframe\n var iframe = document.getElementById(\"modalContent\");\n // When the user clicks the button, open the modal\n btn.addEventListener(\"click\", function() {\n  modal.style.display = \"block\";\n });\n // When the user clicks on <span> (x), close the modal\n span.addEventListener(\"click\", function() {\n  modal.style.display = \"none\";\n });\n // When the user clicks anywhere outside of the modal, close it\n window.addEventListener(\"click\", function(event) {\n  if (event.target === modal) {\n   modal.style.display = \"none\";\n  }\n });\n // Add event listeners to modal links\n modalLinks.forEach(function(link) {\n  link.addEventListener(\"click\", function(e) {\n   e.preventDefault();\n   var src = this.getAttribute(\"data-src\");\n   iframe.src = src;\n   modal.style.display = \"block\";\n  });\n });\n</script>",
