    "html": "<!DOCTYPE html>\n<html lang=\"en\">\n\n  <head>\n    <meta charset=\"UTF-8\">\n    <title>Starry Night</title>\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><link rel=\"stylesheet\" href=\"https://public.codepenassets.com/css/reset-2.0.min.css\">\n<link rel=\"stylesheet\" href=\"./style.css\">\n\n  </head>\n    \n  <body>\n  <div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n<div class=\"star\"></div>\n    \n  </body>\n  \n</html>\n",
